    protected void onFillEntityFullInfo(PSModule pSModule, boolean bl) throws Exception {
        if (bl) {
            if (pSModule.getCodeName() == null) {
                pSModule.setCodeName((String)this.getDefaultValue(this.getWebContext(), "USER", "Module", 25));
            }
            if (pSModule.getOrderValue() == null) {
                pSModule.setOrderValue((Integer)this.getDefaultValue(this.getWebContext(), "", "1000", 9));
            }
            if (pSModule.getPSModuleName() == null) {
                pSModule.setPSModuleName((String)this.getDefaultValue(this.getWebContext(), "USER", "\u6a21\u5757", 25));
            }
            if (pSModule.getSubSysModule() == null) {
                pSModule.setSubSysModule((Integer)this.getDefaultValue(this.getWebContext(), "", "0", 9));
            }
        }
        super.onFillEntityFullInfo((IEntity)pSModule, bl);
        this.onFillEntityFullInfo_PSSysModelGroup(pSModule, bl);
        this.onFillEntityFullInfo_PSSysRef(pSModule, bl);
        this.onFillEntityFullInfo_PSSysSFPub(pSModule, bl);
        this.onFillEntityFullInfo_PSSystem(pSModule, bl);
    }

